public class InnerPrefetchScheduleRecurringPrefetchConfigurationFactory(Action<Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration>
{

    internal InnerPrefetchScheduleRecurringConsumptionFactory RecurringConsumptionFactory { get; set; }

    internal InnerPrefetchScheduleRecurringRetrievalFactory RecurringRetrievalFactory { get; set; }

    protected override Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration Create()
    {
        var recurringPrefetchConfigurationResult = CreateRecurringPrefetchConfiguration();
        factoryAction?.Invoke(recurringPrefetchConfigurationResult);

        return recurringPrefetchConfigurationResult;
    }

    private Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration CreateRecurringPrefetchConfiguration()
    {
        var recurringPrefetchConfigurationResult = new Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration();

        return recurringPrefetchConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PrefetchScheduleTypes.RecurringPrefetchConfiguration result)
    {
        base.CreateChildren(result);

        result.RecurringConsumption ??= RecurringConsumptionFactory?.Build();
        result.RecurringRetrieval ??= RecurringRetrievalFactory?.Build();
    }

} // End Of Class

